// Real scans of the signatory's hand signature over the company stamp
// (source: tools/invoice-templates/assets). Printed on documents the company
// issues as seller. Never generated or redrawn.

const DEI_STAMP_SIGNATURE_B64 = '';

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const STAMP_SIGNATURE: Record<string, { png: () => Uint8Array; width: number; height: number }> = {
  dei: { png: () => decode(DEI_STAMP_SIGNATURE_B64), width: 600, height: 432 },
};
